# Affine coefficients of the frozen semantic contract:
#   out = relu(1.25 * x + 0.75 * y - 0.125)
_X_SCALE = 1.25
_Y_SCALE = 0.75
_BIAS = -0.125

# Cached 0-dim bias scalar, created lazily on the input device.
# It only exists to let the affine offset ride along inside the first kernel.
_BIAS_SCALAR = None


def _bias_scalar(device):
    global _BIAS_SCALAR
    scalar = _BIAS_SCALAR
    if scalar is None or scalar.device != device:
        scalar = torch.tensor(_BIAS, dtype=torch.float32, device=device)
        _BIAS_SCALAR = scalar
    return scalar


def inputs_for(rows, cols):
    x = (torch.linspace(-2, 2, rows * cols, device='cuda', dtype=torch.float32) + 3).reshape(rows, cols)
    return {'x': x, 'y': x.flip(-1)}


def get_inputs():
    return inputs_for(32, 256)


def get_test_cases():
    return [
        {'name': 'minimal', 'category': 'minimal', 'inputs': inputs_for(1, 1)},
        {'name': 'representative', 'category': 'representative', 'inputs': get_inputs()},
        {'name': 'boundary', 'category': 'boundary', 'inputs': inputs_for(2, 32)},
        {'name': 'ragged', 'category': 'ragged', 'inputs': inputs_for(3, 17)},
    ]


def get_benchmark_inputs():
    return [{'name': 'primary', 'inputs': get_inputs()}, {'name': 'small', 'inputs': inputs_for(2, 32)}]


def reference(inputs):
    return torch.relu(inputs['x'] * 1.25 + inputs['y'] * 0.75 - 0.125)


def run(inputs):
    # Three dispatches, one allocation, zero temporaries:
    #   1) out = (-0.125) + 1.25 * x   (bias folded into the scaled add)
    #   2) out += 0.75 * y             (in-place fused multiply-add)
    #   3) out = relu(out)             (in-place)
    x = inputs['x']
    y = inputs['y']
    out = torch.empty_like(x)
    torch.add(_bias_scalar(x.device), x, alpha=_X_SCALE, out=out)
    out.add_(y, alpha=_Y_SCALE)
    torch.relu_(out)
