def run(inputs):
    # Three dispatches, one allocation, zero temporaries:
    #   1) out = (-0.125) + 1.25 * x   (bias folded into the scaled add)
    #   2) out += 0.75 * y             (in-place fused multiply-add)
    #   3) out = relu(out)             (in-place)
    x = inputs['x']
    y = inputs['y']
    out = torch.empty_like(x)
    torch.add(_bias_scalar(x.device), x, alpha=_X_SCALE, out=out)
    out.add_(y, alpha=_Y_SCALE)
    torch.relu_(out)
    return out
